const T = (s:string)=> s.length/3.6;                 // text bytes->tokens
const IMG_BYTES_PER_TOK = 380;                        // measured range 240-525
type Item = {cat:string, tok:number, idx:number, seg:number, key?:string};

async function analyze(sid:string){
  const text = await Bun.file(`${D}/${sid}.jsonl`).text();
  const items:Item[] = []; let calls=0, seg=0;
  const segCalls:number[] = [0];
