      if (o.message?.usage){ calls++; segCalls[seg]=(segCalls[seg]||0)+1; }
      if (Array.isArray(c)) for(const b of c){
        if(b.type==="text") items.push({cat:"assistant text", tok:T(b.text||""), idx:segCalls[seg], seg});
        else if(b.type==="thinking") items.push({cat:"thinking", tok:T(b.thinking||""), idx:segCalls[seg], seg});
        else if(b.type==="tool_use"){
          toolById.set(b.id, b.name);
          items.push({cat:`tool_use:${b.name}`, tok:T(JSON.stringify(b.input||{})), idx:segCalls[seg], seg,
