        items.push({cat, tok:T(c), idx:segCalls[seg], seg});
      } else if (Array.isArray(c)) for(const b of c){
        if(b.type==="tool_result"){
          const name = toolById.get(b.tool_use_id) || "unknown";
          let tok=0, img=0;
          const walk=(x:any)=>{ if(typeof x==="string"){tok+=T(x);return;}
            if(Array.isArray(x)){x.forEach(walk);return;}
            if(x&&typeof x==="object"){ if(x.type==="image"&&x.source?.data){img+=x.source.data.length/IMG_BYTES_PER_TOK;return;}
              if(x.type==="text"){tok+=T(x.text||"");return;} Object.values(x).forEach(walk);} };
          walk(b.content);
          if(tok) items.push({cat:`result:${name}`, tok, idx:segCalls[seg], seg});
          if(img) items.push({cat:`IMAGE (${name})`, tok:img, idx:segCalls[seg], seg});
