// Replay each session's real per-call context increments under different
// autoCompactWindow caps and total the cache-read that would be billed.
const D = process.env.HOME + "/.claude/projects/-Users-burakemre-Code-lobu";
const { readdirSync } = await import("fs");

type Sess = { sid: string; first: string; ctx: number[] };
const sessions: Sess[] = [];
for (const f of readdirSync(D).filter((x) => x.endsWith(".jsonl"))) {
  const text = await Bun.file(`${D}/${f}`).text();
  const ctx: number[] = [];
  let first = "";
  for (const line of text.split("\n")) {
    if (!line) continue;
    let o: any;
    try { o = JSON.parse(line); } catch { continue; }
    if (!first && o.timestamp) first = o.timestamp;
    const u = o.message?.usage;
    if (o.type === "assistant" && u)
      ctx.push((u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.input_tokens || 0));
  }
  if (ctx.length > 50) sessions.push({ sid: f.replace(".jsonl", ""), first, ctx });
}

// Observed post-compaction floor: the context right after a big drop.
const floors: number[] = [];
for (const s of sessions)
  for (let i = 1; i < s.ctx.length; i++)
    if (s.ctx[i] < s.ctx[i - 1] * 0.6 && s.ctx[i - 1] > 150000) floors.push(s.ctx[i]);
floors.sort((a, b) => a - b);
const FLOOR = floors[Math.floor(floors.length / 2)] || 60000;
console.log(`observed post-compaction floor: median ${FLOOR.toLocaleString()} tok (n=${floors.length} compactions seen)`);

// Increments = per-call context growth, with resets dropped.
function increments(s: Sess) {
  const inc: number[] = [];
  for (let i = 1; i < s.ctx.length; i++) {
    const d = s.ctx[i] - s.ctx[i - 1];
    if (d > 0 && d < 200000) inc.push(d);
  }
  return inc;
}

function simulate(s: Sess, cap: number) {
  const inc = increments(s);
  if (!inc.length) return { billed: 0, compactions: 0 };
  let ctx = Math.min(s.ctx[0], FLOOR);
  let billed = 0, comp = 0;
  // Trigger at 92% of the window (harness compacts before hard limit).
  const trigger = cap * 0.92;
  for (let i = 0; i < inc.length; i++) {
    ctx += inc[i];
    if (ctx > trigger) { ctx = FLOOR; comp++; }
    billed += ctx;
  }
  return { billed, compactions: comp };
}

const CUT = new Date("2026-08-07T15:51:37Z").getTime();
const before = sessions.filter((s) => new Date(s.first).getTime() < CUT);

// Calibrate: does the sim reproduce the observed BEFORE -> 400K change?
const caps = [1000000, 500000, 400000, 300000, 250000, 200000, 150000];
const actualBefore = before.reduce((a, s) => a + s.ctx.reduce((x, y) => x + y, 0), 0);
const actualCalls = before.reduce((a, s) => a + s.ctx.length, 0);
console.log(`\nBEFORE corpus: ${before.length} sessions, ${actualCalls.toLocaleString()} calls, ${(actualBefore / 1e6).toFixed(0)}M billed context (ACTUAL)\n`);
console.log("cap".padStart(9), "sim billed".padStart(12), "vs 1M sim".padStart(10), "compactions".padStart(12), "avg ctx/call".padStart(13));
let base = 0;
for (const cap of caps) {
  let billed = 0, comp = 0;
  for (const s of before) { const r = simulate(s, cap); billed += r.billed; comp += r.compactions; }
  if (!base) base = billed;
  console.log(
    (cap / 1000 + "K").padStart(9),
    ((billed / 1e6).toFixed(0) + "M").padStart(12),
    (((billed - base) / base) * 100).toFixed(1).padStart(9) + "%",
    String(comp).padStart(12),
    Math.round(billed / actualCalls).toLocaleString().padStart(13)
  );
}

