// Reconstruct each session as an ordered item stream, rebuild the billed-context
// trajectory, calibrate against real usage, then apply interventions.
const D = process.env.HOME + "/.claude/projects/-Users-burakemre-Code-lobu";
const T = (s: string) => s.length / 3.6;
const FLOOR = 61395;

type Item = { cat: string; tok: number; endsTurn: boolean; cmd?: string };

async function stream(sid: string) {
  const text = await Bun.file(`${D}/${sid}.jsonl`).text();
  const items: Item[] = [];
  const toolById = new Map<string, any>();
  let realCalls = 0, realBilled = 0;
  for (const line of text.split("\n")) {
    if (!line) continue;
    let o: any; try { o = JSON.parse(line); } catch { continue; }
    const c = o.message?.content;
    if (o.type === "assistant") {
      const u = o.message?.usage;
      if (u) { realCalls++; realBilled += (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.input_tokens || 0); }
      if (Array.isArray(c)) for (const b of c) {
        if (b.type === "text") items.push({ cat: "assistant_text", tok: T(b.text || ""), endsTurn: false });
        else if (b.type === "thinking") items.push({ cat: "thinking", tok: T(b.thinking || ""), endsTurn: false });
        else if (b.type === "tool_use") {
          toolById.set(b.id, b.name);
          items.push({ cat: "use:" + b.name, tok: T(JSON.stringify(b.input || {})), endsTurn: true, cmd: b.name === "Bash" ? (b.input?.command || "") : undefined });
        }
      }
    } else if (o.type === "user") {
      if (typeof c === "string") items.push({ cat: "user", tok: T(c), endsTurn: false });
      else if (Array.isArray(c)) for (const b of c) {
        if (b.type === "tool_result") {
          const name = toolById.get(b.tool_use_id) || "unknown";
          let tok = 0;
          const walk = (x: any) => {
            if (typeof x === "string") { tok += T(x); return; }
            if (Array.isArray(x)) { x.forEach(walk); return; }
            if (x && typeof x === "object") { if (x.type === "image") { tok += (x.source?.data?.length || 0) / 380; return; } if (x.type === "text") { tok += T(x.text || ""); return; } Object.values(x).forEach(walk); }
          };
          walk(b.content);
          items.push({ cat: "res:" + name, tok, endsTurn: false });
        } else if (b.type === "text") items.push({ cat: "user", tok: T(b.text || ""), endsTurn: false });
      }
    }
  }
  return { items, realCalls, realBilled };
}

// An API call happens after each tool_use (round trip) plus one per assistant turn.
function billed(items: Item[], cap: number) {
  let ctx = FLOOR, total = 0, calls = 0, comp = 0;
  const trig = cap * 0.92;
  for (const it of items) {
    ctx += it.tok;
    if (it.endsTurn) {
      if (ctx > trig) { ctx = FLOOR; comp++; }
      total += ctx; calls++;
    }
  }
  return { total, calls, comp };
}

const EXPLORE = /^\s*\(?\s*(grep|rg|cat|ls|find|head|tail|sed|awk|wc|file|stat|jq|tree|du)\b/;
const isExplore = (it: Item) => it.cat === "use:Bash" && !!it.cmd && EXPLORE.test(it.cmd);

const SIDS = process.argv.slice(2);
const all: Item[][] = [];
let realCalls = 0, realBilled = 0;
for (const s of SIDS) { const r = await stream(s); all.push(r.items); realCalls += r.realCalls; realBilled += r.realBilled; }

const capNow = 400000, capPrev = 500000;
let simPrev = { total: 0, calls: 0, comp: 0 };
for (const items of all) { const r = billed(items, capPrev); simPrev.total += r.total; simPrev.calls += r.calls; simPrev.comp += r.comp; }
console.log(`CALIBRATION (5 heavy sessions)`);
console.log(`  actual: ${realCalls.toLocaleString()} API calls, ${(realBilled / 1e6).toFixed(0)}M billed, avg ${Math.round(realBilled / realCalls).toLocaleString()}/call`);
console.log(`  sim@500K: ${simPrev.calls.toLocaleString()} calls, ${(simPrev.total / 1e6).toFixed(0)}M billed, avg ${Math.round(simPrev.total / simPrev.calls).toLocaleString()}/call`);

function intervene(cap: number, dropExploreFrac: number, batchFactor: number) {
  let total = 0, calls = 0, comp = 0, dropped = 0;
  for (const items of all) {
    let n = 0;
    const kept = items.filter((it) => {
      if (!isExplore(it)) return true;
      n++;
      // keep 1 of every `batchFactor`, and drop dropExploreFrac of the rest
      const drop = (n % Math.max(1, Math.round(1 / (1 - dropExploreFrac))) !== 0);
      if (drop) dropped++;
      return !drop;
    });
    // dropping a tool_use also drops the following result
    const out: Item[] = [];
    for (let i = 0; i < kept.length; i++) out.push(kept[i]);
