const bashes = all.flat().filter((i) => i.cat === "use:Bash").length;
const turns = all.flat().filter((i) => i.endsTurn).length;
console.log(`exploration Bash calls: ${explores} of ${bashes} Bash (${((explores / bashes) * 100).toFixed(0)}%), ${((explores / turns) * 100).toFixed(1)}% of all tool round-trips\n`);

console.log("intervention".padEnd(44), "billed".padStart(9), "vs today".padStart(9), "calls".padStart(8));
const show = (label: string, r: { total: number; calls: number }) =>
  console.log(label.padEnd(44), ((r.total / 1e6).toFixed(0) + "M").padStart(9), (((r.total - base400.t) / base400.t) * 100).toFixed(1).padStart(8) + "%", r.calls.toLocaleString().padStart(8));

for (const f of [0.5, 0.7]) show(`batch exploration Bash ${f * 100}% fewer @400K`, intervene(400000, f, 1));
for (const cap of [300000, 250000, 200000]) {
  let t = 0, c = 0; for (const items of all) { const r = billed(items, cap); t += r.total; c += r.calls; }
  show(`cap ${cap / 1000}K alone`, { total: t, calls: c });
}
show(`cap 300K + 70% fewer exploration Bash`, intervene(300000, 0.7, 1));
show(`cap 250K + 70% fewer exploration Bash`, intervene(250000, 0.7, 1));

