const hist = new Map<number, number>();
let turns = 0, tools = 0;
const soloByTool = new Map<string, number>();
// consecutive assistant turns that each issue exactly one READ-ONLY tool -> mergeable
const RO = /^(Read|Grep|Glob|Bash)$/;
const ROBASH = /^\s*\(?\s*(grep|rg|cat|ls|find|head|tail|sed|awk|wc|file|stat|jq|git (status|log|diff|show|grep)|gh (pr|run) (view|list|checks)|du|tree)\b/;
let mergeableRuns = 0, mergeableCalls = 0;
for (const sid of SIDS) {
  const text = await Bun.file(`${D}/${sid}.jsonl`).text();
  let run = 0;
  for (const line of text.split("\n")) {
    if (!line) continue;
    let o: any; try { o = JSON.parse(line); } catch { continue; }
    if (o.type !== "assistant" || !Array.isArray(o.message?.content)) continue;
    const tu = o.message.content.filter((b: any) => b.type === "tool_use");
    if (!tu.length) continue;
    turns++; tools += tu.length;
    hist.set(tu.length, (hist.get(tu.length) || 0) + 1);
    if (tu.length === 1) soloByTool.set(tu[0].name, (soloByTool.get(tu[0].name) || 0) + 1);
    const readonly = tu.length === 1 && RO.test(tu[0].name) &&
      (tu[0].name !== "Bash" || ROBASH.test(tu[0].input?.command || ""));
    if (readonly) { run++; }
    else { if (run > 1) { mergeableRuns++; mergeableCalls += run - 1; } run = 0; }
  }
  if (run > 1) { mergeableRuns++; mergeableCalls += run - 1; }
}
