const D = process.env.HOME + "/.claude/projects/-Users-burakemre-Code-lobu";
const T = (s: string) => s.length / 3.6;
const FLOOR = 61395;
type Item = { tok: number; endsTurn: boolean; tool?: string; cmd?: string };

const RO = /^(Read|Grep|Glob|Bash)$/;
const ROBASH = /^\s*\(?\s*(grep|rg|cat|ls|find|head|tail|sed|awk|wc|file|stat|jq|git (status|log|diff|show|grep)|gh (pr|run) (view|list|checks)|du|tree)\b/;

async function stream(sid: string) {
  const text = await Bun.file(`${D}/${sid}.jsonl`).text();
  const items: Item[] = [];
  const toolById = new Map<string, string>();
  for (const line of text.split("\n")) {
    if (!line) continue;
    let o: any; try { o = JSON.parse(line); } catch { continue; }
    const c = o.message?.content;
    if (o.type === "assistant" && Array.isArray(c)) {
      for (const b of c) {
        if (b.type === "text") items.push({ tok: T(b.text || ""), endsTurn: false });
        else if (b.type === "thinking") items.push({ tok: T(b.thinking || ""), endsTurn: false });
        else if (b.type === "tool_use") { toolById.set(b.id, b.name); items.push({ tok: T(JSON.stringify(b.input || {})), endsTurn: true, tool: b.name, cmd: b.input?.command }); }
      }
    } else if (o.type === "user") {
      if (typeof c === "string") items.push({ tok: T(c), endsTurn: false });
      else if (Array.isArray(c)) for (const b of c) {
        if (b.type === "tool_result") {
          let tok = 0;
          const walk = (x: any) => { if (typeof x === "string") { tok += T(x); return; } if (Array.isArray(x)) { x.forEach(walk); return; } if (x && typeof x === "object") { if (x.type === "image") { tok += (x.source?.data?.length || 0) / 380; return; } if (x.type === "text") { tok += T(x.text || ""); return; } Object.values(x).forEach(walk); } };
          walk(b.content); items.push({ tok, endsTurn: false });
        } else if (b.type === "text") items.push({ tok: T(b.text || ""), endsTurn: false });
      }
    }
  }
  return items;
}

